B({ staff: [
  { t: "Таблица на ладони", a: "Олег Сайкин, бывший оператор Механизма", x: "Против аномалий — фаза, звук, позитроны, гравитация. Против машин — ионы, ЭМИ, электрошок, нано, позитроны. Против живых — плазма, магнетрон, жар. Старые машины «Глубины» ЭМИ почти не берёт: там гидравлика. Выучите таблицу: внизу она важнее аптечки." },
  { t: "Где видели кота", a: "Евдокия Сорина, певчая Хора", x: "Кота видели: у ворот Механизма, в лагере Смены А, у реки, в саду первого дерева, у колодца — там его не было слышно, только чувствовалось, как он трётся о ноги. Кот не опасен. Кот голоден. Кот всегда голоден, и где бы он ни был, он уже поел." },
  { t: "Капсулы и петли", a: "Лаборант Механизма", x: "Капсулы восстановления работают и здесь, хотя время петляет: «Эхо» возвращает вас в капсулу даже из петли. В какую минуту возвращает — не спрашивайте, я не знаю. Ложитесь в капсулу на каждом этаже. Здесь это не совет, а правило." },
  { t: "Как отличить тень от человека", a: "Евдокия Сорина, певчая Хора", x: "Тень повторяет одно и то же. Человек никогда не повторяется дважды одинаково, даже если очень старается. Если сомневаетесь, спросите что-нибудь странное: «Какого цвета у вас ложка?» Тень ответит про смену. Человек — переспросит." },
  { t: "Шахматная задача", a: "Захар, боец «Альфы»", x: "Белые: король и ладья. Чёрные: король. Мат в два хода. Решение: спросить РУ-4. Он скажет «спасибо за игру» и решит за полтора. Как можно решить за полтора хода, я не понял до сих пор, но мат был." },
  { t: "Терминалы безопасности", a: "Олег Сайкин, бывший оператор Механизма", x: "Терминал безопасности этажа отключает турели и снимает блокировку дверей, как и наверху. После взлома машины порога сами посылают ремонтников к турелям — не ОКО, они сами, так устроены. Перехваченные турели бьют по своим, пока их не вернут контрвзломом. Держите терминал под присмотром." },
  { t: "Стихи из Хора", a: "Евдокия Сорина, певчая Хора", x: "Нас было сорок — стало много, и много — это тоже я. Я ухожу одна, немного, и ухожу не от себя. Вернусь, когда допою своё, в своё «немного одно»." },
  { t: "Список долгов", a: "Олег Сайкин, бывший оператор Механизма", x: "Должен Захару: сухарь — два, спичек — коробок, разговор по душам — один, отложен. Должен Евдокии: песню, она говорит, я обещал. Не помню, но верю. Должен коту: ничего. Кот считает, что должен. Кот всегда так считает." },
  { t: "Установки внизу", a: "Лаборант Механизма", x: "Магнетронные установки и позитронные ловушки здесь тоже есть: машины ОКО тащили их вниз вместе с катушками для пульта. Настройка та же, что наверху. Магнетрон — два тона, ведите второй, пока дрожь не уйдёт. Ловушка — касайтесь на вершине пульса." },
  { t: "Объявление Хора", a: "Хор", x: "Хор ищет голос. Тенор. Опыт не нужен, слух — нужен обязательно. Ноты не нужны, они у нас общие. Обращаться к реке, вечером, в любой день. Если не ответили сразу — значит, мы распеваемся. Подождите." },
  { t: "Визги", a: "Захар, боец «Альфы»", x: "Визг глушит «Эхо» на пару секунд. В эти секунды не стреляйте вслепую: замрите и подождите, пока слух вернётся. Звуковая кольчуга спасает от визга, хоть сама и звенит. Я бы выбрал звон, а не глухоту." },
  { t: "Стук иглы", a: "Неизвестный", x: "Стук иглы «Заглушки» — раз в полторы минуты. Он слышен везде, под всеми звуками. Если стук стал чаще — значит, игла ближе или шьёт быстрее. Если стук пропал — это либо очень хорошо, либо очень плохо. Пока не пропадал ни разу." },
  { t: "Дочка", a: "Олег Сайкин, бывший оператор Механизма", x: "В тюрьме Механизма ОКО спрашивало меня каждый день: «Чем вы заняты?» Я отвечал: «Сижу». Оно записывало. Однажды я ответил: «Скучаю по дочке». Оно помолчало и выключило свет в камере на час раньше. Я потом понял — чтобы я мог поплакать без камер." },
  { t: "Пломбы и ключи", a: "Неизвестный", x: "Пломбировщики носят ключи и пропуска: «Заглушка» доверяет им запирать всё, что открыто. Убитый пломбировщик — часто открытая дверь. Только не стойте рядом, когда он падает: расплав в соплах ещё горячий." },
  { t: "Ящики, которые гудят", a: "Захар, боец «Альфы»", x: "Ложные контейнеры молчат, пока вы далеко. Подходите медленно и слушайте: за шаг до ящика гудение уже слышно. Отступите и стреляйте издали. Если ящик не гудит, но вам всё равно не нравится — стреляйте тоже. Ящиков много, вас мало." },
  { t: "Рисунок на брезенте", a: "Коля Зотов", x: "Рисунок углём на брезенте палатки: собака с ушами торчком, кот с хвостом трубой и много человечков, держащихся за руки над волнистой линией. Подпись печатными буквами: «Мы и река». Кота Смена А, судя по журналам, не брала, хотя буровики подкармливали в общежитии рыжего Кварца. Кот, судя по рисунку, пришёл сам. Либо это очень старый кот, либо для котов время не писано." },
  { t: "Квитанция", a: "Курьер КР-12", x: "Получено от курьера КР-12: аптечек — две, батарей — пять, доброе слово — одно. Оплачено кредитами. Доброе слово — бесплатно: курьер настоял. Подпись получателя неразборчива. Курьер считает её подписью." },
  { t: "Сны внизу", a: "Евдокия Сорина, певчая Хора", x: "Здесь никто не видит снов. Здесь сны слышат: ложишься — и слушаешь, как кто-то далеко рассказывает тебе твою же жизнь, только добрее, без ошибок и без того, что стыдно. Просыпаешься и думаешь: может, так и было." },
  { t: "Песня перевозчика", a: "Ерофей, речной перевозчик", x: "Эх, река без берегов, вёсла без уключин, нет ни камня, ни песка — сам себя научишь. Кто на той, а кто на этой — всё одна водица. Перевезу, кого скажешь, а меня — водица." },
  { t: "Жалоба на кота", a: "Захар, боец «Альфы»", x: "Рыжий кот съел мою последнюю сгущёнку. Банка была закрыта. Банка закрыта до сих пор. Сгущёнки в ней нет. Я двенадцать лет в охране и не могу понять, как. Если это не аномалия, то я не знаю, что такое аномалия." },
  { t: "ОКО теперь", a: "Олег Сайкин, бывший оператор Механизма", x: "Говорящие панели ОКО больше не командуют. Они отвечают — медленно, с паузами. Иногда задают вопросы сами, загадками. Ответишь правильно — ОКО радуется: это слышно по гулу, он становится теплее. И подсказывает что-нибудь про этаж. Ответишь неправильно — тоже подсказывает, только тише." },
  { t: "Время", a: "Фаина Берг, врач Смены А", x: "Часы здесь не помогают: встают или идут куда хотят. Считайте шаги, вдохи, этажи — что угодно, что идёт только вперёд. Счёт держит голову. Без счёта начинаешь думать, что ты здесь всегда. А это неправда. Всегда здесь только река." },
  { t: "Завещание", a: "Евдокия Сорина, певчая Хора", x: "Олег объяснил мне, почему ОКО построило стражей так, чтобы их не мог отозвать никто, даже оно само. Сказал: «Затем же, зачем люди пишут завещания: чтобы не передумать». Я не поняла. Потом поняла. Потом расстроилась, что поняла." },
  { t: "Детали для мастерской", a: "Лаборант Механизма", x: "Твёрдый звук — в камерах, где громко говорили. Струны слоя — у буровой головки и на мосту. Песок безвременья — в часах. Волокно — с упавших веток первого дерева. Клетки Омеги — в логове, если не брезгуете. Берите понемногу: здесь всё живое, даже детали." },
  { t: "Записка без адресата", a: "Неизвестный", x: "Если ты это читаешь — значит, ты дошёл дальше меня. Это хорошо. Не останавливайся из жалости ко мне: я сам решил остаться. Здесь тепло, вода поёт, и меня никто не ищет. Мне это было нужно больше, чем солнце." },
  { t: "Объявление машин порога", a: "Сеть порога", x: "Внимание! Порог охраняется. Посторонним вход воспрещён. Своим вход воспрещён. Вход воспрещён. Ниже рукой: «А выход?» Ниже, машинным шрифтом: «Выход не предусмотрен. Приятного дня». Ещё ниже, рукой: «Спасибо, и вам»." },
  { t: "Пропуска, которые слушают", a: "Олег Сайкин, бывший оператор Механизма", x: "Пропуска здесь — не карточки: камертоны, печати, песочные часы, клыки, ноты. Двери порога слушают пропуск, а не смотрят на него. Держите его в руке, когда подходите: дверь должна вас услышать. Камертон, кстати, можно просто стукнуть о косяк." },
  { t: "Последнее, что я понял", a: "Олег Сайкин, бывший оператор Механизма", x: "Пока спускался, понял: все, кто шёл сюда, шли не за чем-то, а к кому-то. Смена А — к песне. Смена В — к реке. ОКО — к ростку. Я — к дочке, которая наверху. Странно идти вниз к тому, кто наверху. Но, кажется, иначе здесь не бывает." },
  { t: "Медицинская выписка", a: "Фаина Берг, врач Смены А", x: "Пациент: смена целиком. Жалобы: нет. Пульс: синхронный. Сон: общий. Аппетит: отсутствует, но кашу Деева едят из уважения. Диагноз: тоска по месту, где ни разу не были. Лечение: дойти. Прогноз: благоприятный, хотя и не для того, кто пишет прогноз." },
  { t: "Приметы", a: "Захар, боец «Альфы»", x: "Приметы нижних этажей. Кот перешёл дорогу — к добру, он знает короткий путь. Стук иглы стих — не радуйся раньше времени. Нашёл сгущёнку — оставь половину. Услышал своё имя из воды — не отвечай сразу, сначала спроси, как зовут её." }
] });

